\begin{theorem}\label{th-conv-rate}  In the settings of problem \eqref{opt-pb} consider the sequences $(x_n)_{n\in\N},\,(y_n)_{n\in\N}$ generated by Algorithm \eqref{generaldiscrete}. Assume that $g$ is bounded from below and that $(x_n)_{n\in\N}$ is bounded, let $\ol x\in\crit(g)$ be such that $\lim_{n\To+\infty}x_n=\ol x$ and suppose that
$$H:\R^n\times \R^n\To\R,\,H(x,y)=g(x)+\frac{1}{2}\|x-y\|^2$$
fulfills the {\L}ojasiewicz property at $(\ol x,\ol x)\in\crit H$ with {\L}ojasiewicz exponent  $\t\in\left(0,\frac12\right].$ Then, for every $p>0$ there exist $a_1,a_2,a_3,a_4>0$ and $\ol k\in\N$ such that the following statements hold true:
\begin{itemize}
\item[$(\emph{a}_1)$] $g(y_{n})-g(\ol x)\le a_1 \frac{1}{n^p}$ for  every $n> \ol k$,
\item[$(\emph{a}_2)$] $g(x_{n})-g(\ol x)\le a_2\frac{1}{n^p}$ for  every $n>\ol k$,
\item[$(\emph{a}_3)$] $\|x_n-\ol x\|\le a_3 \frac{1}{n^{\frac{p}{2}}}$ for  every $n>\ol k$,
\item[$(\emph{a}_4)$] $\|y_n-\ol x\|\le a_4 \frac{1}{n^{\frac{p}{2}}}$ for all  $n>\ol k$.
\end{itemize}
\end{theorem}

