\begin{lemma}\label{desc} Let $g:\R^m\To\R$ be Fr\`echet differentiable with $L_g$ Lipschitz continuous gradient. Then
$$g(y)\le g(x)+\<\n g(x),y-x\>+\frac{L_g}{2}\|y-x\|^2,\,\forall x,y\in\R^m.$$
\end{lemma}

\begin{theorem}\label{decreasing} In the settings of problem \eqref{opt-pb}, for some starting points $x_0=y_0\in\R^m$ let $(x_n)_{n\in\N},\,(y_n)_{n\in\N}$ be the sequences generated by the numerical scheme \eqref{generaldiscrete}. Consider the sequences
 $$A_{n-1}=\frac{2-s L_g}{2s}\left(\frac{(1+\b)n+\a}{n+\a}\right)^2-\frac{\b n((1+\b)n+\a)}{s(n+\a)^2},$$
$$C_{n-1}=\frac{2-s L_g}{2s}\frac{\b n-\b}{n+\a-1}\frac{(1+\b)n+\a}{n+\a}-\frac{1}{2s}\frac{\b n-\b}{n+\a-1}\frac{\b n}{n+\a}$$
and
$$\d_n=A_{n-1}-C_{n-1}$$
for all $n\in\N,\,n\ge 1$.

 Then, there exists $N\in\N$ such that %for all $n\ge N$ one has
\begin{itemize}
\item[(i)] The sequence $ \left(g(y_{n})+\d_{n}\|x_{n}-x_{n-1}\|^2\right)_{n\ge N}$ is decreasing and $\d_n>0$ for all $n\ge N$.
\end{itemize}
Assume that $g$ is bounded from below. Then, the following statements hold.
\begin{itemize}
\item[(ii)] The sequence $\left(g(y_{n})+\d_{n}\|x_{n}-x_{n-1}\|^2\right)_{n\in \N}$ is convergent;
\item[(iii)] $\sum_{n\ge 1}\|x_n-x_{n-1}\|^2<+\infty.$
\end{itemize}
\end{theorem}

\begin{lemma}\label{regularization} In the settings of problem \eqref{opt-pb}, for some starting points $x_0=y_0\in\R^m$ consider the sequences $(x_n)_{n\in\N},\,(y_n)_{n\in\N}$ generated by Algorithm \eqref{generaldiscrete}. Assume that $g$ is bounded from below and consider the function
$$H:\R^m\times\R^m\To\R,\,H(x,y)=g(x)+\frac12\|y-x\|^2.$$
Consider further the sequence
$$u_n=\sqrt{2\d_n}(x_{n}-x_{n-1})+y_n\mbox{, for all }n\in \N,$$
where $\d_n$ was defined in Theorem \ref{decreasing}. Then, the following statements hold true.
\begin{itemize}
\item[(i)] $\omega((u_n)_{n\in\N})=\omega((y_n)_{n\in\N})=\omega((x_n)_{n\in\N})\subseteq\crit g$;
\item[(ii)] There exists and is finite the limit $\lim_{n\To+\infty}H(y_n,u_n)$;
\item[(iii)] $\omega((y_n,u_n)_{n\in\N})\subseteq\crit H=\{(x,x)\in\R^m\times\R^m:x\in\crit g\}$;
\item[(iv)] $\|\n H(y_n,u_n)\|\le \frac{1}{s}\|x_{n+1}-x_n\|+\left(\frac{\b  n}{s(n+\a)}+2\sqrt{2\d_n}\right)\|x_{n}-x_{n-1}\|$ for all $n\in\N$;
\item[(v)]  $\|\n H(y_n,u_n)\|^2\le \frac{2}{s^2}\|x_{n+1}-x_n\|^2+2\left(\left(\frac{\b n}{s(n+\a)}-\sqrt{2\d_n}\right)^2+\d_n\right)\|x_{n}-x_{n-1}\|^2$ for all $n\in\N$;
\item[(vi)] $H$ is finite and constant on $\omega((y_n,u_n)_{n\in\N}).$
\end{itemize}

Assume that $(x_n)_{n\in\N}$ is bounded. Then,
\begin{itemize}
\item[(vii)] $\omega((y_n, u_n)_{n\in\N})$ is nonempty and compact;
\item[(viii)] $\lim_{n\To+\infty} \dist((y_n,u_n),\omega((y_n,u_n)_{n\in\N}))=0.$
\end{itemize}
\end{lemma}

\begin{lemma}\label{unif-KL-property} Let $\Omega\subseteq \R^n$ be a compact set and let $f:\R^n\rightarrow \R$ be a differentiable function. Assume that $f$ is constant on $\Omega$ and $f$ satisfies the KL property at each point of $\Omega$.
Then there exist $\varepsilon,\eta >0$ and $\varphi\in \Theta_{\eta}$ such that for all $\ol x\in\Omega$ and for all $x$ in the intersection
\begin{equation}\label{int} \{x\in\R^n: \dist(x,\Omega)<\varepsilon\}\cap \{x\in\R^n: f(\ol x)<f(x)<f(\ol x)+\eta\}\end{equation}
the following inequality holds \begin{equation}\label{KL-ineq}\varphi'(f(x)-f(\ol x))\|\n f(x)\|\geq 1.\end{equation}
\end{lemma}

\begin{theorem}\label{convergence} In the settings of problem \eqref{opt-pb}, for some starting points $x_0=y_0\in\R^m$ consider the sequences $(x_n)_{n\in\N},\,(y_n)_{n\in\N}$ generated by Algorithm \eqref{generaldiscrete}. Assume that $g$ is bounded from below and consider the function
$$H:\R^m\times\R^m\To\R,\,H(x,y)=g(x)+\frac12\|y-x\|^2.$$
Assume that $(x_n)_{n\in\N}$ is bounded and $H$ is a KL function. Then the following statements are true
\begin{itemize}
\item[(a)] $\sum_{n\ge 1}\|x_n-x_{n-1}\|<+\infty;$
\item[(b)] there exists ${x}\in\crit(g)$ such that $\lim_{n\To+\infty}x_n={x}.$
\end{itemize}
\end{theorem}

